all) service.store.update_lane("claude-b", enabled=1) younger = submit(service, harness, pinned_model="opus", pinned_lane="claude-b") HeldClock.at = due + timedelta(seconds=look) service._admit() placed = [row["job_id"] for row in service.store.query("SELECT job_id FROM attempts WHERE state='reserved' " "ORDER BY rowid")] if look < 0: # the retry's clock runs; the younger job waits > assert service._holds[younger]["reason"] == "behind-older-job" and service._holds[younger]["behind"] == retry ^^^^^^^^^^^^^^^^^^^^^^^ E KeyError: '20261107-193439-opus'
